/*
 * High-performance portfolio calculations using C extension
 *
 * Both routines operate directly on the NumPy buffers (zero-copy when the
 * caller already supplies contiguous float64 arrays).  The accumulation order
 * mirrors the Python baseline exactly: for the risk we first form S*x row by
 * row and then take the weighted dot product x^T (S x).
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

/* Convert an arbitrary input into a 1-D contiguous float64 array.  Returns a
 * new reference (or NULL on failure).  Non-array inputs (e.g. Python lists)
 * are converted by NumPy. */
static PyArrayObject* as_1d_double(PyObject *obj, const char *name) {
    PyArrayObject *arr = (PyArrayObject *)PyArray_FROM_OTF(
        obj, NPY_DOUBLE, NPY_ARRAY_C_CONTIGUOUS | NPY_ARRAY_ALIGNED);
    if (arr == NULL)
        return NULL;
    if (PyArray_NDIM(arr) != 1) {
        PyErr_Format(PyExc_ValueError, "%s must be a 1-D array", name);
        Py_DECREF(arr);
        return NULL;
    }
    return arr;
}

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;

    if (!PyArg_ParseTuple(args, "OO:portfolio_risk_c",
                          &weights_obj, &cov_obj))
        return NULL;

    PyArrayObject *weights = as_1d_double(weights_obj, "weights");
    if (weights == NULL)
        return NULL;

    PyArrayObject *cov = (PyArrayObject *)PyArray_FROM_OTF(
        cov_obj, NPY_DOUBLE, NPY_ARRAY_C_CONTIGUOUS | NPY_ARRAY_ALIGNED);
    if (cov == NULL) {
        Py_DECREF(weights);
        return NULL;
    }

    if (PyArray_NDIM(cov) != 2) {
        PyErr_SetString(PyExc_ValueError, "cov_matrix must be a 2-D array");
        Py_DECREF(weights);
        Py_DECREF(cov);
        return NULL;
    }

    const npy_intp n = PyArray_DIM(weights, 0);
    if (PyArray_DIM(cov, 0) != n || PyArray_DIM(cov, 1) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "cov_matrix must be square and match weights length");
        Py_DECREF(weights);
        Py_DECREF(cov);
        return NULL;
    }

    const double *restrict w = (const double *)PyArray_DATA(weights);
    const double *restrict S = (const double *)PyArray_DATA(cov);

    /* Step 1 + 2 fused: the baseline stores temp = S*x then accumulates
     * x^T * temp; keeping the same per-row order preserves bit-level
     * agreement with the reference implementation. */
    double risk_squared = 0.0;
    for (npy_intp i = 0; i < n; ++i) {
        const double *restrict row = S + i * n;
        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; ++j)
            row_sum += row[j] * w[j];
        risk_squared += w[i] * row_sum;
    }

    Py_DECREF(weights);
    Py_DECREF(cov);

    if (risk_squared < 0.0)
        risk_squared = 0.0;  /* guard tiny negative round-off before sqrt */
    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *returns_obj;

    if (!PyArg_ParseTuple(args, "OO:portfolio_return_c",
                          &weights_obj, &returns_obj))
        return NULL;

    PyArrayObject *weights = as_1d_double(weights_obj, "weights");
    if (weights == NULL)
        return NULL;

    PyArrayObject *rets = as_1d_double(returns_obj, "expected_returns");
    if (rets == NULL) {
        Py_DECREF(weights);
        return NULL;
    }

    const npy_intp n = PyArray_DIM(weights, 0);
    if (PyArray_DIM(rets, 0) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected_returns must have equal length");
        Py_DECREF(weights);
        Py_DECREF(rets);
        return NULL;
    }

    const double *restrict w = (const double *)PyArray_DATA(weights);
    const double *restrict r = (const double *)PyArray_DATA(rets);

    double total = 0.0;
    for (npy_intp i = 0; i < n; ++i)
        total += w[i] * r[i];

    Py_DECREF(weights);
    Py_DECREF(rets);
    return PyFloat_FromDouble(total);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();  // Initialize NumPy C API
    return PyModule_Create(&moduledef);
}

/*
 * High-performance portfolio calculations using C extension
 *
 * Both routines operate directly on NumPy buffers (zero-copy when the caller
 * already supplies contiguous float64 arrays).  The accumulation order mirrors
 * the Python baseline exactly: for the risk we first form S*x row by row and
 * then take the weighted dot product x^T (S x).
 *
 * Nested Python lists (the form produced by the baseline's generate_test_data)
 * are converted with a tight C loop instead of NumPy's generic sequence
 * converter.  The fast path is only taken when the input is a list/tuple of
 * list/tuple rows containing exact Python floats, i.e. no Python code can run
 * while we are reading, so the buffers cannot be mutated underneath us.
 * Anything else falls back to PyArray_FROM_OTF.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

#define IS_SEQ(obj) (PyList_Check(obj) || PyTuple_Check(obj))

static inline Py_ssize_t row_len(PyObject *row) {
    if (PyList_Check(row))
        return PyList_GET_SIZE(row);
    if (PyTuple_Check(row))
        return PyTuple_GET_SIZE(row);
    return -1;
}

static inline PyObject *row_item(PyObject *row, Py_ssize_t j) {
    return PyList_Check(row) ? PyList_GET_ITEM(row, j)
                             : PyTuple_GET_ITEM(row, j);
}

/* Generic (slower) conversion used whenever the fast path does not apply. */
static PyArrayObject *convert_slow(PyObject *obj) {
    return (PyArrayObject *)PyArray_FROM_OTF(
        obj, NPY_DOUBLE, NPY_ARRAY_C_CONTIGUOUS | NPY_ARRAY_ALIGNED);
}

/* Convert to a contiguous 1-D float64 array, using a fast path for
 * list/tuple of exact floats.  Returns a new reference or NULL. */
static PyArrayObject *to_double_1d(PyObject *obj, const char *name) {
    PyArrayObject *arr = NULL;

    if (IS_SEQ(obj)) {
        Py_ssize_t n = PySequence_Fast_GET_SIZE(obj);
        npy_intp dims[1] = {(npy_intp)n};
        arr = (PyArrayObject *)PyArray_SimpleNew(1, dims, NPY_DOUBLE);
        if (arr == NULL)
            return NULL;

        double *out = (double *)PyArray_DATA(arr);
        for (Py_ssize_t i = 0; i < n; ++i) {
            PyObject *v = row_item(obj, i);
            if (!PyFloat_CheckExact(v)) {
                Py_DECREF(arr);
                arr = convert_slow(obj);
                break;
            }
            out[i] = PyFloat_AS_DOUBLE(v);
        }
    } else {
        arr = convert_slow(obj);
    }

    if (arr == NULL)
        return NULL;
    if (PyArray_NDIM(arr) != 1) {
        PyErr_Format(PyExc_ValueError, "%s must be a 1-D array", name);
        Py_DECREF(arr);
        return NULL;
    }
    return arr;
}

/* Convert to a contiguous 2-D float64 array.  Returns a new reference or
 * NULL.  The fast path allocates first and abandons the allocation if the
 * input turns out not to fit the exact-float pattern. */
static PyArrayObject *to_double_2d(PyObject *obj, const char *name) {
    PyArrayObject *arr = NULL;

    if (IS_SEQ(obj)) {
        Py_ssize_t n = PySequence_Fast_GET_SIZE(obj);

        if (n == 0) {
            npy_intp dims[2] = {0, 0};
            return (PyArrayObject *)PyArray_SimpleNew(2, dims, NPY_DOUBLE);
        }

        PyObject *first = row_item(obj, 0);
        Py_ssize_t m = row_len(first);

        if (m >= 0) {
            npy_intp dims[2] = {(npy_intp)n, (npy_intp)m};
            arr = (PyArrayObject *)PyArray_SimpleNew(2, dims, NPY_DOUBLE);
            if (arr == NULL)
                return NULL;

            double *out = (double *)PyArray_DATA(arr);
            int ok = 1;

            for (Py_ssize_t i = 0; i < n && ok; ++i) {
                PyObject *row = row_item(obj, i);
                if (row_len(row) != m) {
                    ok = 0;
                    break;
                }
                double *dst = out + i * m;
                for (Py_ssize_t j = 0; j < m; ++j) {
                    PyObject *v = row_item(row, j);
                    if (!PyFloat_CheckExact(v)) {
                        ok = 0;
                        break;
                    }
                    dst[j] = PyFloat_AS_DOUBLE(v);
                }
            }

            if (!ok) {
                Py_DECREF(arr);
                arr = NULL;
            }
        }
    }

    if (arr == NULL)
        arr = convert_slow(obj);

    if (arr == NULL)
        return NULL;
    if (PyArray_NDIM(arr) != 2) {
        PyErr_Format(PyExc_ValueError, "%s must be a 2-D array", name);
        Py_DECREF(arr);
        return NULL;
    }
    return arr;
}

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;

    if (!PyArg_ParseTuple(args, "OO:portfolio_risk_c",
                          &weights_obj, &cov_obj))
        return NULL;

    PyArrayObject *weights = to_double_1d(weights_obj, "weights");
    if (weights == NULL)
        return NULL;

    PyArrayObject *cov = to_double_2d(cov_obj, "cov_matrix");
    if (cov == NULL) {
        Py_DECREF(weights);
        return NULL;
    }

    const npy_intp n = PyArray_DIM(weights, 0);
    if (PyArray_DIM(cov, 0) != n || PyArray_DIM(cov, 1) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "cov_matrix must be square and match weights length");
        Py_DECREF(weights);
        Py_DECREF(cov);
        return NULL;
    }

    const double *restrict w = (const double *)PyArray_DATA(weights);
    const double *restrict S = (const double *)PyArray_DATA(cov);

    /* Step 1 + 2 fused: the baseline stores temp = S*x then accumulates
     * x^T * temp; keeping the same per-row order preserves bit-level
     * agreement with the reference implementation. */
    double risk_squared = 0.0;
    for (npy_intp i = 0; i < n; ++i) {
        const double *restrict row = S + i * n;
        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; ++j)
            row_sum += row[j] * w[j];
        risk_squared += w[i] * row_sum;
    }

    Py_DECREF(weights);
    Py_DECREF(cov);

    if (risk_squared < 0.0)
        risk_squared = 0.0;  /* guard tiny negative round-off before sqrt */
    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *returns_obj;

    if (!PyArg_ParseTuple(args, "OO:portfolio_return_c",
                          &weights_obj, &returns_obj))
        return NULL;

    PyArrayObject *weights = to_double_1d(weights_obj, "weights");
    if (weights == NULL)
        return NULL;

    PyArrayObject *rets = to_double_1d(returns_obj, "expected_returns");
    if (rets == NULL) {
        Py_DECREF(weights);
        return NULL;
    }

    const npy_intp n = PyArray_DIM(weights, 0);
    if (PyArray_DIM(rets, 0) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected_returns must have equal length");
        Py_DECREF(weights);
        Py_DECREF(rets);
        return NULL;
    }

    const double *restrict w = (const double *)PyArray_DATA(weights);
    const double *restrict r = (const double *)PyArray_DATA(rets);

    double total = 0.0;
    for (npy_intp i = 0; i < n; ++i)
        total += w[i] * r[i];

    Py_DECREF(weights);
    Py_DECREF(rets);
    return PyFloat_FromDouble(total);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();  // Initialize NumPy C API
    return PyModule_Create(&moduledef);
}

